    },
    [98] = {
      beijing = 1741,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "I took the scepter, then turned my back to pack up the luggage. That image floated up once again in my mind, and my cheeks started to burn.",
