      role1 = 4106000,
      role2 = 402107,
      role3 = 402206,
      role5 = 4106401,
      ruchang = 9,
      sentence = "As he said that, he took the bag that I'd packed up and secured it to Griffy's back. Then he picked up the ancient tome and confirmed our next destination.",
