    },
    [106] = {
      beijing = 1741,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "I felt a stinging feeling, like my heart was drowning in deep water, and there was a tension reverberating in my chest.",
      next = {107}
    },
    [107] = {
      beijing = 1741,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "I'd lived in this land for too long, witnessed the rise and fall of many kingdoms, and been through times of war and peace from antiquity to the present.",
      next = {108}
    },
    [108] = {
      beijing = 1741,
      dialog = 3,
      music = "404_Hazy_Starry_Night",
      renwu = "npc",
      sentence = "But I didn't understand where these emotions right now were coming from, or what they meant.",
      next = {109}
    },
    [109] = {
      beijing = 1351,
      dialog = 3,
      music = "62_2020anniversary_rec",
      renwu = "npc",
      sentence = "We continued on to many different places.",
