    },
    [110] = {
      beijing = 1351,
      dialog = 3,
      music = "62_2020anniversary_rec",
      renwu = "npc",
      sentence = "We crossed the desert, flew over the ocean, scaled the highest mountain peak, and plumbed the deepest abyss.",
